<script setup lang="ts">import { onMounted } from "vue"; const props = defineProps<{ kind: "developer" | "about" | "privacy" | "terms" }>(); const content = { developer: { title: "开发者服务", eyebrow: "FOR CREATORS", intro: "把你的原创网页游戏带到更多玩家面前。", sections: [["支持的内容", "平台支持 HTML5、WebGL、同站资源、受控 iframe 和安全的新窗口启动。所有游戏需要提供清晰的版权授权、年龄评级、语言与运行要求。"], ["审核与发布", "我们会进行内容安全、版权、移动适配和启动行为检查。资料完整后通常在三个工作日内完成首次处理；发布版本不可原地覆盖。"], ["提交前检查", "准备游戏名称、简介、分类、标签、图标、封面、启动清单、允许 origin、第三方依赖和版权证明。提交入口将在开发者工作台开放后启用。"]] }, about: { title: "关于星屿游廊", eyebrow: "ABOUT THE ARCADE", intro: "星屿游廊是一个独立创作的中文网页游戏发现与启动平台。", sections: [["我们的方向", "我们相信好游戏不一定需要长时间安装或复杂账号。平台用清晰分类、可信内容说明和安全启动边界，帮助玩家快速找到适合当下的作品。"], ["内容原则", "平台展示自制或取得合法授权的内容，不复制其他网站的品牌、文案、素材、代码或界面。"], ["版权投诉", "如发现版权或内容安全问题，请通过详情页的投诉入口提交具体游戏、素材地址、权利证明和联系方式。"]] }, privacy: { title: "隐私政策", eyebrow: "PRIVACY", intro: "生效日期：2026 年 8 月 25 日。我们只收集提供服务所需的信息。", sections: [["必要数据", "安全日志、请求 ID、错误和内容状态用于保证平台正常运行。收藏与最近玩默认保存在你的浏览器中，只保存版本化 slug 列表。"], ["可选分析", "分析埋点需要单独授权。拒绝分析不影响浏览、启动或收藏。我们不会向第三方游戏注入平台 token，也不读取游戏自身的存档。"], ["你的选择", "你可以通过浏览器清除 localStorage，或联系我们申请数据访问、删除和账号注销。"]] }, terms: { title: "服务条款", eyebrow: "TERMS", intro: "生效日期：2026 年 8 月 25 日。使用平台即表示你理解以下边界。", sections: [["免费服务", "平台提供免费的游戏发现和启动服务，内容、可用性和发布时间可能因维护、安全、版权或运营原因调整。"], ["第三方内容", "第三方游戏由其开发者负责。启动页会说明受控配置、来源和网络边界；平台不会承诺控制外部新窗口中的内容。"], ["安全与未成年人", "请根据页面年龄提示使用服务。发现不适宜内容时，请立即停止并通过投诉入口反馈。"]] }}[props.kind]; onMounted(() => { document.title = `${content.title}｜星屿游廊`; });</script><template><div class="portal-page policy-page"><section class="portal-page-heading"><span class="portal-eyebrow">{{ content.eyebrow }}</span><h1>{{ content.title }}</h1><p>{{ content.intro }}</p></section><section v-for="section in content.sections" :key="section[0]" class="policy-section"><h2>{{ section[0] }}</h2><p>{{ section[1] }}</p></section></div></template>
